insert into opposing_positions (id, case_id, title, strongest_support, weak_point, commentary_angles, origin, added_by_team_id, created_at, created_by) values
  ('7921fc9c-0e4a-4f6a-a4c3-ef7eab1dd71f', (select id from cases where number = 1), 'They argue AI is neutral', '(1) war already involves human panic, bias and fatigue; (2) AI could identify threats faster and more accurately; (3) the military answers to elected officials, companies don''t.', 'a system that ranks targets embeds choices about training data, thresholds and acceptable error. Excel doesn''t choose who lives.', array['ask how training data and thresholds can be value-free.', 'If they argue companies should decide: ask what happens when a less careful company sells the same tool.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301'),
  ('e848c7c4-ed5b-47db-8ebe-2ef39abfd096', (select id from cases where number = 1), 'They argue companies should decide', '(1) war already involves human panic, bias and fatigue; (2) AI could identify threats faster and more accurately; (3) the military answers to elected officials, companies don''t.', 'a system that ranks targets embeds choices about training data, thresholds and acceptable error. Excel doesn''t choose who lives.', array['ask what happens when a less careful company sells the same tool.', 'If they argue only accuracy matters: ask who is responsible when an accurate system makes its rare mistake.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301'),
  ('839d15df-6567-4494-ab88-50aaa1ff2498', (select id from cases where number = 1), 'They argue only accuracy matters', '(1) war already involves human panic, bias and fatigue; (2) AI could identify threats faster and more accurately; (3) the military answers to elected officials, companies don''t.', 'a system that ranks targets embeds choices about training data, thresholds and acceptable error. Excel doesn''t choose who lives.', array['ask who is responsible when an accurate system makes its rare mistake.', 'If they argue AI is neutral: ask how training data and thresholds can be value-free.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301'),
  ('04f44643-3b54-4544-a5a3-7c6e8eb8baba', (select id from cases where number = 3), 'If they condemn Japan only: ask how their principle applies to U.S. monuments.', '(1) Japan''s government acknowledged the military''s role (Kono Statement, 1993) and reached a 2015 agreement with South Korea; (2) present-day Japanese people aren''t responsible; (3) a city shouldn''t conduct foreign policy.', 'apologies that survivors reject don''t close the question, and using diplomatic ties to pressure a city to remove a memorial treats memory as a bargaining chip.', array['If they condemn Japan only: ask how their principle applies to U.S. monuments.', 'If they side with diplomacy: ask what survivors are owed if apologies don''t satisfy them.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302'),
  ('24e1ca78-b1db-484d-9d51-2cd89c731687', (select id from cases where number = 3), 'If they side with diplomacy: ask what survivors are owed if apologies don''t sati', '(1) Japan''s government acknowledged the military''s role (Kono Statement, 1993) and reached a 2015 agreement with South Korea; (2) present-day Japanese people aren''t responsible; (3) a city shouldn''t conduct foreign policy.', 'apologies that survivors reject don''t close the question, and using diplomatic ties to pressure a city to remove a memorial treats memory as a bargaining chip.', array['If they side with diplomacy: ask what survivors are owed if apologies don''t satisfy them.', 'If they say "it depends": ask what it depends on, and offer our four tests.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302'),
  ('82b51d27-f3f2-4903-bfa9-d5b1374d489d', (select id from cases where number = 3), 'If they say "it depends": ask what it depends on, and offer our four tests.', '(1) Japan''s government acknowledged the military''s role (Kono Statement, 1993) and reached a 2015 agreement with South Korea; (2) present-day Japanese people aren''t responsible; (3) a city shouldn''t conduct foreign policy.', 'apologies that survivors reject don''t close the question, and using diplomatic ties to pressure a city to remove a memorial treats memory as a bargaining chip.', array['If they say "it depends": ask what it depends on, and offer our four tests.', 'If they condemn Japan only: ask how their principle applies to U.S. monuments.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302'),
  ('987fe224-d69e-419d-bdb8-9aca6b75daac', (select id from cases where number = 4), 'They argue a duty exists', '(1) higher earnings, (2) better treatment by courts and employers, (3) social and romantic success (all from the case''s research).', 'the right response to unjust advantages is to reduce the bias in institutions, not to demand that everyone chase the ideal.', array['ask whether it applies to people who can''t meet the standard.', 'If they defend looksmaxxing fully: ask about minors and hardmaxxing risks.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
  ('676ca4e5-36c2-42fd-8964-1a0185533c89', (select id from cases where number = 4), 'If they defend looksmaxxing fully: ask about minors and hardmaxxing risks.', '(1) higher earnings, (2) better treatment by courts and employers, (3) social and romantic success (all from the case''s research).', 'the right response to unjust advantages is to reduce the bias in institutions, not to demand that everyone chase the ideal.', array['If they defend looksmaxxing fully: ask about minors and hardmaxxing risks.', 'If they condemn all appearance work: ask about haircuts and braces.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
  ('4905ab10-328b-40b0-8a04-3e0b02e65100', (select id from cases where number = 4), 'If they condemn all appearance work: ask about haircuts and braces.', '(1) higher earnings, (2) better treatment by courts and employers, (3) social and romantic success (all from the case''s research).', 'the right response to unjust advantages is to reduce the bias in institutions, not to demand that everyone chase the ideal.', array['If they condemn all appearance work: ask about haircuts and braces.', 'If they argue a duty exists: ask whether it applies to people who can''t meet the standard.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
  ('8b2a1cc3-fe5b-44a6-803d-46ac09535740', (select id from cases where number = 5), 'If they defend all markets: ask about the soldier''s indictment.', '(1) markets aggregate dispersed knowledge, (2) Kalshi''s 2024 track record, (3) governments and businesses can plan better.', 'the same accuracy is possible without money on death; forecasting tournaments like the Good Judgment Project do it without betting on lives (verify before citing).', array['If they defend all markets: ask about the soldier''s indictment.', 'If they ban all markets: ask about weather and economic data.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304'),
  ('2c2f2df2-39dd-4e04-a167-8fd5dffdeb78', (select id from cases where number = 5), 'If they ban all markets: ask about weather and economic data.', '(1) markets aggregate dispersed knowledge, (2) Kalshi''s 2024 track record, (3) governments and businesses can plan better.', 'the same accuracy is possible without money on death; forecasting tournaments like the Good Judgment Project do it without betting on lives (verify before citing).', array['If they ban all markets: ask about weather and economic data.', 'If they rely on accuracy: ask whether accuracy justifies profiting from leaked secrets.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304'),
  ('756b3856-fed4-47db-8a18-d22b000cd725', (select id from cases where number = 5), 'If they rely on accuracy: ask whether accuracy justifies profiting from leaked s', '(1) markets aggregate dispersed knowledge, (2) Kalshi''s 2024 track record, (3) governments and businesses can plan better.', 'the same accuracy is possible without money on death; forecasting tournaments like the Good Judgment Project do it without betting on lives (verify before citing).', array['If they rely on accuracy: ask whether accuracy justifies profiting from leaked secrets.', 'If they defend all markets: ask about the soldier''s indictment.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304'),
  ('cc79a846-de3f-4d78-9e64-9dc59bb83585', (select id from cases where number = 7), 'If they defend the lawsuits fully: ask whether every suit should end in a fix, a', '(1) no one can plead ignorance of the Civil Rights Act; (2) every day of delay excludes someone; (3) without the $4,000, nobody sues.', 'the Richmond suit produced a closed restaurant and no ramp, forever.', array['If they defend the lawsuits fully: ask whether every suit should end in a fix, and what the Richmond closure achieved.', 'If they condemn the lawsuits as extortion: ask who enforces the ADA otherwise, and how they answer Bad Daddy''s and DRA''s results.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301'),
  ('1a2f13ac-7a68-4ed7-9abb-4ba4a08bb5ec', (select id from cases where number = 7), 'If they condemn the lawsuits as extortion: ask who enforces the ADA otherwise, a', '(1) no one can plead ignorance of the Civil Rights Act; (2) every day of delay excludes someone; (3) without the $4,000, nobody sues.', 'the Richmond suit produced a closed restaurant and no ramp, forever.', array['If they condemn the lawsuits as extortion: ask who enforces the ADA otherwise, and how they answer Bad Daddy''s and DRA''s results.', 'If they attack Bouyer personally: motive doesn''t change whether a barrier is real.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301'),
  ('6f2cd775-4b60-42f5-b9e8-d5c5d7c4a6be', (select id from cases where number = 7), 'If they attack Bouyer personally: motive doesn''t change whether a barrier is rea', '(1) no one can plead ignorance of the Civil Rights Act; (2) every day of delay excludes someone; (3) without the $4,000, nobody sues.', 'the Richmond suit produced a closed restaurant and no ramp, forever.', array['If they attack Bouyer personally: motive doesn''t change whether a barrier is real.', 'If they defend the lawsuits fully: ask whether every suit should end in a fix, and what the Richmond closure achieved.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301'),
  ('d27eada4-e802-4ede-8b03-a11fe3789173', (select id from cases where number = 9), 'They argue for keeping it', '(1) circumstances change, (2) enforcing old claims can create new injustice, (3) no one alive did wrong.', 'our claim rests on responsibility, not blame.', array['which classic reason still holds now that the GEM is open?', 'If they argue for return: where does their principle stop? Offer our test; press Waldron.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302'),
  ('ce0f3a9f-c829-48ac-8851-71afb6373ac8', (select id from cases where number = 9), 'They argue for return', '(1) circumstances change, (2) enforcing old claims can create new injustice, (3) no one alive did wrong.', 'our claim rests on responsibility, not blame.', array['where does their principle stop? Offer our test; press Waldron.', 'If they settle on loans: why should the injured party be the borrower?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302'),
  ('01690aa7-cb52-4824-9579-50cefd0f8f97', (select id from cases where number = 9), 'If they settle on loans: why should the injured party be the borrower?', '(1) circumstances change, (2) enforcing old claims can create new injustice, (3) no one alive did wrong.', 'our claim rests on responsibility, not blame.', array['If they settle on loans: why should the injured party be the borrower?', 'If they argue for keeping it: which classic reason still holds now that the GEM is open?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302'),
  ('846c9125-8a05-4609-a31b-181e6f7f79f6', (select id from cases where number = 10), 'If they defend an absolute right: ask about public officials and journalism.', '(1) free press, (2) employers'' right to know, (3) history must not be rewritten.', 'an acquittal isn''t information about guilt; using it in hiring treats an innocent person as guilty.', array['If they defend an absolute right: ask about public officials and journalism.', 'If they reject any right: ask about acquittals and revenge porn.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
  ('1de09a30-3e67-45ee-b7c2-0aed81544182', (select id from cases where number = 10), 'If they reject any right: ask about acquittals and revenge porn.', '(1) free press, (2) employers'' right to know, (3) history must not be rewritten.', 'an acquittal isn''t information about guilt; using it in hiring treats an innocent person as guilty.', array['If they reject any right: ask about acquittals and revenge porn.', 'If they don''t tier: ask whether all information is alike.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
  ('868552c6-e663-439a-ab05-5d3878c47b30', (select id from cases where number = 10), 'If they don''t tier: ask whether all information is alike.', '(1) free press, (2) employers'' right to know, (3) history must not be rewritten.', 'an acquittal isn''t information about guilt; using it in hiring treats an innocent person as guilty.', array['If they don''t tier: ask whether all information is alike.', 'If they defend an absolute right: ask about public officials and journalism.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
  ('f0995107-7b34-49ab-a759-70c1510f6a62', (select id from cases where number = 11), 'If they say refuse everything: ask who pays for the vaccines.', '(1) association signals approval, (2) victims deserve solidarity, (3) other funders exist.', 'the case doesn''t show other funders would replace the money, and girls who miss vaccination pay that cost. Distinguish: walking away from Gates personally is different from walking away from the patients.', array['If they say refuse everything: ask who pays for the vaccines.', 'If they say take everything: ask about cartel or Sackler money.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304'),
  ('4298e992-3702-4f7b-bbf5-65a7293aef83', (select id from cases where number = 11), 'If they say take everything: ask about cartel or Sackler money.', '(1) association signals approval, (2) victims deserve solidarity, (3) other funders exist.', 'the case doesn''t show other funders would replace the money, and girls who miss vaccination pay that cost. Distinguish: walking away from Gates personally is different from walking away from the patients.', array['If they say take everything: ask about cartel or Sackler money.', 'If they make claims beyond the case: collegially ask for the source.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304'),
  ('79f5d8d6-9116-46cf-8d8f-4fbd6aa83922', (select id from cases where number = 11), 'If they make claims beyond the case: collegially ask for the source.', '(1) association signals approval, (2) victims deserve solidarity, (3) other funders exist.', 'the case doesn''t show other funders would replace the money, and girls who miss vaccination pay that cost. Distinguish: walking away from Gates personally is different from walking away from the patients.', array['If they make claims beyond the case: collegially ask for the source.', 'If they say refuse everything: ask who pays for the vaccines.']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304'),
  ('15d30941-6131-4515-b58a-f5fefee538e6', (select id from cases where number = 12), 'If they defend China''s rules for public health: did they separate Article 13 fro', '(1) measles spreads faster than literacy campaigns; (2) labels are ignored; (3) countries that restrict more seem fine.', 'comparisons mix many causes. Distinguish: we reject licensing everyone to stop the few.', array['If they defend China''s rules for public health: did they separate Article 13 from Article 4? What happens when the decider is wrong, as with Li Wenliang?', 'If they reject all regulation: how do they handle checkable, false, harmful claims sold for profit?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301'),
  ('47e29d05-d44a-4f5a-ad8b-518ac8857a5b', (select id from cases where number = 12), 'If they reject all regulation: how do they handle checkable, false, harmful clai', '(1) measles spreads faster than literacy campaigns; (2) labels are ignored; (3) countries that restrict more seem fine.', 'comparisons mix many causes. Distinguish: we reject licensing everyone to stop the few.', array['If they reject all regulation: how do they handle checkable, false, harmful claims sold for profit?', 'If they rely on platforms or literacy alone: who reviews platforms? What protects children who never take the course?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301'),
  ('3d74ecf0-9a97-4a1f-a35d-76927466e0fe', (select id from cases where number = 12), 'If they rely on platforms or literacy alone: who reviews platforms? What protect', '(1) measles spreads faster than literacy campaigns; (2) labels are ignored; (3) countries that restrict more seem fine.', 'comparisons mix many causes. Distinguish: we reject licensing everyone to stop the few.', array['If they rely on platforms or literacy alone: who reviews platforms? What protects children who never take the course?', 'If they defend China''s rules for public health: did they separate Article 13 from Article 4? What happens when the decider is wrong, as with Li Wenliang?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301'),
  ('2e5179d4-0a09-47ae-911d-85e83983ca1e', (select id from cases where number = 13), 'If they say only attackers are responsible: how do they treat accomplices, or He', '(1) autonomy; (2) B after A doesn''t mean A caused B; (3) the case gives no causal data.', 'responsibility isn''t a fixed pie. Distinguish: our claim is about raising risk, which is wrong even when no single attack can be traced, like drunk driving; where we assert a link, we use evidence such as a manifesto.', array['If they say only attackers are responsible: how do they treat accomplices, or Henry II?', 'If they want to criminalize stochastic terrorism: who enforces it, and how do they protect protest movements?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302'),
  ('0ee3c6c1-bbd6-4153-9c5d-756603b73e0c', (select id from cases where number = 13), 'If they want to criminalize stochastic terrorism: who enforces it, and how do th', '(1) autonomy; (2) B after A doesn''t mean A caused B; (3) the case gives no causal data.', 'responsibility isn''t a fixed pie. Distinguish: our claim is about raising risk, which is wrong even when no single attack can be traced, like drunk driving; where we assert a link, we use evidence such as a manifesto.', array['If they want to criminalize stochastic terrorism: who enforces it, and how do they protect protest movements?', 'If they lean on one political example: does their principle give the same answer for the other side?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302'),
  ('086a099a-a31a-4a90-9a75-922d1551deaa', (select id from cases where number = 13), 'If they lean on one political example: does their principle give the same answer', '(1) autonomy; (2) B after A doesn''t mean A caused B; (3) the case gives no causal data.', 'responsibility isn''t a fixed pie. Distinguish: our claim is about raising risk, which is wrong even when no single attack can be traced, like drunk driving; where we assert a link, we use evidence such as a manifesto.', array['If they lean on one political example: does their principle give the same answer for the other side?', 'If they say only attackers are responsible: how do they treat accomplices, or Henry II?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302'),
  ('351014e7-0d6e-487b-a4e6-e4208d04786d', (select id from cases where number = 14), 'If they deny company responsibility: how do they distinguish a chatbot from a bo', '(1) courts protect expressive works; (2) personal responsibility; (3) parents control access.', 'a 14-year-old in crisis is the paradigm case where choice isn''t fully free.', array['If they deny company responsibility: how do they distinguish a chatbot from a book?', 'If they want a full ban: what about the benefits, and adults?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
  ('670a12a5-0bd1-4bde-adae-1ae5b083eb84', (select id from cases where number = 14), 'If they want a full ban: what about the benefits, and adults?', '(1) courts protect expressive works; (2) personal responsibility; (3) parents control access.', 'a 14-year-old in crisis is the paradigm case where choice isn''t fully free.', array['If they want a full ban: what about the benefits, and adults?', 'If they rely on age limits: how are they enforced, and what about vulnerable adults?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
  ('eae66b7b-fe49-4755-b576-e6e91330ec32', (select id from cases where number = 14), 'If they rely on age limits: how are they enforced, and what about vulnerable adu', '(1) courts protect expressive works; (2) personal responsibility; (3) parents control access.', 'a 14-year-old in crisis is the paradigm case where choice isn''t fully free.', array['If they rely on age limits: how are they enforced, and what about vulnerable adults?', 'If they deny company responsibility: how do they distinguish a chatbot from a book?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
  ('b97c1a99-a059-4349-b1bc-27b97ec58ecd', (select id from cases where number = 15), 'They argue full personhood', '(1) property status invites abuse; (2) corporations and rivers already have legal personhood; (3) India''s dolphin designation.', 'enforcement and standards matter more.', array['what duties would animals hold?', 'If they defend property status: what protects a stray?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304'),
  ('49c446a1-db69-4101-95c4-471e39d3d48c', (select id from cases where number = 15), 'If they defend property status: what protects a stray?', '(1) property status invites abuse; (2) corporations and rivers already have legal personhood; (3) India''s dolphin designation.', 'enforcement and standards matter more.', array['If they defend property status: what protects a stray?', 'If they rely on utilitarianism alone: how do they avoid cherry-picking outcomes?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304'),
  ('7846ed57-7556-4fbb-815f-097b2ad55896', (select id from cases where number = 15), 'If they rely on utilitarianism alone: how do they avoid cherry-picking outcomes?', '(1) property status invites abuse; (2) corporations and rivers already have legal personhood; (3) India''s dolphin designation.', 'enforcement and standards matter more.', array['If they rely on utilitarianism alone: how do they avoid cherry-picking outcomes?', 'If they argue full personhood: what duties would animals hold?']::text[], 'team', '33333333-3333-3333-3333-333333333333', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304')
insert into one_pagers (id, team_id, case_id, version, body, created_at, created_by, previous_body, change_note, signed_off_by, drive_doc_id, drive_pdf_exported, origin_tag) values
  ('c4f351df-041c-4e70-9f56-3bd6d6c04283', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 1, '{"claims":[{"text":"Even a more accurate AI would not remove the core objection: decisions to kill need meaningful human judgment and a responsible human.","logic_line":"Because autonomous killing creates a responsibility gap (S1), humans \"in the loop\" drift into rubber-stamping (S2), and greater distance makes war easier to start (S3), accuracy alone cannot justify removing human judgment.","supports":["The responsibility gap When a machine selects and engages a target, no one may be fully answerable: not the programmer, the commander, or the machine.","Automation bias People formally \"in the loop\" come to defer to the system''s recommendation.","Distance lowers the threshold for war Each step that removes risk from the side using force makes force easier to choose."]},{"text":"A company may refuse uses it judges unethical, but the binding limits on lethal autonomy and domestic mass surveillance belong in public law.","logic_line":"Because makers share responsibility for foreseeable uses of what they build (S1), democratic governments, not vendors, must set national policy (S2), and mass surveillance threatens the democratic accountability the military itself relies on (S3), the right answer is public, legal guardrails rather than private vetoes.","supports":["Makers can be complicit in foreseeable uses A company that knowingly supplies a tool for a use it believes is wrong shares responsibility for that use.","Democratic legitimacy cuts the other way too Unelected companies shouldn''t set military policy for a democracy, as the Pentagon argues in the case. That means the durable fix is law.","Mass surveillance of citizens undermines democracy itself People who know they are always watched speak and organize less freely."]}],"counterclaim":{"text":"AI is a neutral tool like Excel, refusing it costs lives, and only the law, not a company, should bind the military.","concede":"(3) that''s why Claim 2 puts the limits in law.","distinguish":"(2) we accept decision support; the objection is to delegating the kill decision.","rebut":"a system that ranks targets embeds choices about training data, thresholds and acceptable error. Excel doesn''t choose who lives."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"Even a more accurate AI would not remove the core objection: decisions to kill need meaningful human judgment and a responsible human.","supports":["The responsibility gap When a machine selects and engages a target, no one may be fully answerable: not the programmer, the commander, or the machine.","Automation bias People formally \"in the loop\" come to defer to the system''s recommendation.","Distance lowers the threshold for war Each step that removes risk from the side using force makes force easier to choose."]},{"id":"c2","label":"A company may refuse uses it judges unethical, but the binding limits on lethal autonomy and domestic mass surveillance belong in public law.","supports":["Makers can be complicit in foreseeable uses A company that knowingly supplies a tool for a use it believes is wrong shares responsibility for that use.","Democratic legitimacy cuts the other way too Unelected companies shouldn''t set military policy for a democracy, as the Pentagon argues in the case. That means the durable fix is law.","Mass surveillance of citizens undermines democracy itself People who know they are always watched speak and organize less freely."]}],"counter":"AI is a neutral tool like Excel, refusing it costs lives, and only the law, not a company, should bind the military.","crux":"fewer battlefield errors through machine speed *versus* keeping moral judgment and accountability for killing in human hands.","trap":"the case mixes two questions: (1) should lethal decisions be automated, and (2) who gets to set the limits, a company or the government? Answer them separately.","thesis":"Accuracy alone would not settle the question, because killing requires a responsible human judgment that can''t be delegated; and while a company may refuse uses it believes are wrong, the lasting limits on lethal autonomy and domestic surveillance should be set by democratic law."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"fewer battlefield errors through machine speed versus keeping moral judgment and accountability for killing in human hands.","right":"Value B","note":"the case mixes two questions: (1) should lethal decisions be automated, and (2) who gets to set the limits, a company or the government? Answer them separately."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"Civilians in conflict zones","stake":"Being misidentified as targets; or being protected by better accuracy","voice":"No"},{"who":"Soldiers","stake":"Safety; moral injury; responsibility for outcomes","voice":"Barely"},{"who":"U.S. citizens","stake":"Freedom from mass surveillance","voice":"Indirect"},{"who":"AI companies and their workers","stake":"Complicity in uses they find wrong","voice":"Yes"},{"who":"Military and elected officials","stake":"Security; democratic authority over force","voice":"Yes"},{"who":"Adversaries and future conflicts","stake":"Escalation risk if war gets cheaper to wage","voice":"No"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"Anthropic, maker of Claude, negotiated with the U.S. government over military use of its AI, holding two limits: no lethal autonomous warfare without human oversight, and no mass surveillance of Americans","source":"Reuters, March 2026"},{"order":2,"text":"After the government objected, Anthropic sued, claiming it was unlawfully punished for refusing to remove its safety guardrails","source":"Sriram, Reuters, March 9, 2026"},{"order":3,"text":"CEO Dario Amodei is not opposed to AI weapons in principle; his concern is that current systems aren''t reliable enough","source":"Seetharaman, Reuters, March 4, 2026"},{"order":4,"text":"Pentagon view: AI is a neutral tool, like Excel; the military should be bound by U.S. law, elected officials and the chain of command, not company policies","source":"Case text"},{"order":5,"text":"A May 1, 2026 Department of War release said AI would speed data synthesis and support warfighter decisions","source":"Department of War"},{"order":6,"text":"A wargame pitting GPT-5.2, Claude Sonnet 4 and Gemini 3 ended in a tactical nuclear strike in 95% of games; models treated tactical nuclear use as a manageable risk","source":"Tom''s Hardware, Feb 26, 2026"},{"order":7,"text":"For AI: war is already full of human error, bias, panic and fatigue; AI may reduce mistakes; refusing it could be irresponsible","source":"Case text"},{"order":8,"text":"Against: AI changes the moral character of decisions, adds distance, invites overreliance by humans \"in the loop,\" and makes war easier to start","source":"Case text"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"philosopher Robert Sparrow''s \"Killer Rob","one_line":"philosopher Robert Sparrow''s \"Killer Robots\" (2007) argues that just war requires someone who can be held responsible for each death. Our team put it simply: letting AI use weapons turns a moral decision into a program."},{"name":"Kant''s humanity formula (never treat peo","one_line":"Kant''s humanity formula (never treat people merely as tools or data points) explains why a target is owed a human judgment."},{"name":"this is a chilling-effect argument roote","one_line":"this is a chilling-effect argument rooted in privacy and free-association values. A limit on domestic mass surveillance protects the democratic accountability that gives the military its authority."},{"name":"Virtue ethics asks what a responsible bu","one_line":"Virtue ethics asks what a responsible builder does; the answer includes refusing to sell for uses it believes are wrong."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"If AI became as accurate as humans, would the ethical objection disappear? (the case''s own question)","a":"No: accuracy answers \"will it hit the right target?\" but not \"who is responsible?\" or \"will war become too easy?\""},{"q":"Should private AI companies be able to control how governments use their tools in warfare and surveillance? (team''s version)","a":"A company may refuse to supply uses it judges wrong, but the binding limits belong in public law, not in either side''s private say-so."},{"q":"Is it permissible to use AI in lethal military decisions?","a":"As decision support under meaningful human judgment, yes; as the decider, no."},{"q":"If AI were provably more accurate and saved civilians, would you still require a human?","a":"Yes, because accountability and the threshold for war don''t depend on accuracy; but we''d welcome AI as decision support."},{"q":"Isn''t a human \"in the loop\" just a rubber stamp?","a":"Often, which is why we require meaningful judgment: time to review, authority to refuse, and training against automation bias."},{"q":"What about fast defensive systems that shoot down incoming missiles?","a":"Different: they target munitions, not people, in seconds. Our concern is decisions to kill people."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('e8d453ac-193e-458c-ba12-adedfcae9bdd', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 1, '{"claims":[{"text":"San Francisco was justified in keeping the memorial, and diplomatic pressure is not a valid reason to remove it.","logic_line":"Because San Francisco has a real connection to this history (S1), memorials serve justice for victims whose suffering hasn''t been adequately acknowledged (S2), and the statue honors victims rather than accusing today''s Japanese people (S3), keeping it was justified.","supports":["Real connection San Francisco has large Chinese and Korean communities, and the U.S. military reportedly took part in the abuse, so the U.S. shares some accountability.","Memory is a form of justice owed to victims When wrongs go unacknowledged, public memory is one of the few remedies left.","Remembrance is not accusation The statue honors \"all other women affected by such crimes,\" not only victims of Japan."]},{"text":"The right standard for public memory has four tests, and it binds the U.S. as much as Japan.","logic_line":"Because a principle we apply to others must apply to ourselves (S1), societies that confront their own wrongs show it can be done well (S2), and the community most connected to a history should decide, with victims at the center (S3), the U.S. must hold its own monuments to the same four tests.","supports":["Consistency Memorializing another country''s wrongs while honoring our own perpetrators is a double standard.","Acknowledgment works Countries can face their own atrocities without collapse.","Local communities decide, with victims at the center"]}],"counterclaim":{"text":"Memorials abroad inflame nationalism, damage today''s relations, and ignore that Japan has apologized.","concede":"(2) that''s why S3 of Claim 1 matters.","distinguish":"(3) honoring victims in your own city isn''t foreign policy.","rebut":"apologies that survivors reject don''t close the question, and using diplomatic ties to pressure a city to remove a memorial treats memory as a bargaining chip."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"San Francisco was justified in keeping the memorial, and diplomatic pressure is not a valid reason to remove it.","supports":["Real connection San Francisco has large Chinese and Korean communities, and the U.S. military reportedly took part in the abuse, so the U.S. shares some accountability.","Memory is a form of justice owed to victims When wrongs go unacknowledged, public memory is one of the few remedies left.","Remembrance is not accusation The statue honors \"all other women affected by such crimes,\" not only victims of Japan."]},{"id":"c2","label":"The right standard for public memory has four tests, and it binds the U.S. as much as Japan.","supports":["Consistency Memorializing another country''s wrongs while honoring our own perpetrators is a double standard.","Acknowledgment works Countries can face their own atrocities without collapse.","Local communities decide, with victims at the center"]}],"counter":"Memorials abroad inflame nationalism, damage today''s relations, and ignore that Japan has apologized.","crux":"the right of victims and communities to public memory *versus* diplomatic harmony and a nation''s interest in how its past is portrayed.","trap":"the case looks like it''s about Japan, but its last third turns the question on the U.S. A team that condemns Japan while ignoring Confederate statues and plantation weddings will be caught in a double standard. Our claims are built to apply to both.","thesis":"Public memorials are justified when a community has a real connection to the history, victims'' voices are at the center, and the purpose is remembrance rather than shaming a present-day people; by that standard San Francisco was right to keep its memorial, and the U.S. owes the same honesty about its own wrongs."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"the right of victims and communities to public memory versus diplomatic harmony and a nation''s interest in how its past is portrayed.","right":"Value B","note":"the case looks like it''s about Japan, but its last third turns the question on the U.S. A team that condemns Japan while ignoring Confederate statues and plantation weddings will be caught in a double standard. Our claims are built to apply to both."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"Surviving comfort women and their families","stake":"Recognition, dignity, truth","voice":"Barely"},{"who":"Korean and Chinese American communities in San Francisco","stake":"Public acknowledgment of their history","voice":"Indirect"},{"who":"Japanese and Japanese American communities","stake":"Fair portrayal; not being blamed collectively","voice":"No"},{"who":"City governments","stake":"Choosing what public space honors","voice":"Yes"},{"who":"National governments","stake":"Diplomacy, national image","voice":"Yes"},{"who":"Descendants of the enslaved and Native Americans","stake":"Whether U.S. memory is honest about U.S. wrongs","voice":"Raised at the end of the case"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"In 2018 Osaka cut its sister-city ties with San Francisco over a statue honoring \"comfort women\"","source":"BBC News, April 4, 2018"},{"order":2,"text":"\"Comfort women\" were women trafficked and sexually abused by the Japanese Imperial Army during World War II","source":"Case text"},{"order":3,"text":"The statue, \"Women''s Column of Strength,\" stands near San Francisco''s Chinatown and honors thousands of Korean and Chinese women and all women affected by such crimes","source":"World Heritage USA"},{"order":4,"text":"The memorial''s stated values: memory, dialogue, peace and reconciliation, transformation and justice","source":"World Heritage USA"},{"order":5,"text":"Japan''s embassy objected to a similar planned statue in New Zealand, warning of diplomatic harm; the council rejected it, citing lack of public support","source":"BBC and Reuters, April 2026"},{"order":6,"text":"New Zealand opponents cited community tension, political readings and relevance; supporters cited reflection, acknowledging harm and education","source":"Case text"},{"order":7,"text":"Japan has offered few apologies or reparations that survivors consider satisfactory","source":"Comfort Women Justice Coalition"},{"order":8,"text":"San Francisco has far larger Chinese and Korean communities than New Zealand, and the U.S. military reportedly took part in the abuse; New Zealand had no such involvement","source":"NBC News, April 27, 2007"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"corrective justice says whoever is wrong","one_line":"corrective justice says whoever is wronged is owed repair; philosopher Avishai Margalit''s *The Ethics of Memory* (2002) argues that communities have duties to remember grave wrongs. The case reports that survivors consider Japan''s apologies and reparations unsatisfactory."},{"name":"Kant''s humanity formula supports the vic","one_line":"Kant''s humanity formula supports the victims: their suffering can''t be treated as a bargaining chip in diplomatic relations."},{"name":"Kant''s universalizability test: act only","one_line":"Kant''s universalizability test: act only on a rule everyone could follow. The case notes many U.S. statues honor conquistadors and Confederate leaders while few honor Native Americans or enslaved people."},{"name":"New Zealand''s council rejected its statu","one_line":"New Zealand''s council rejected its statue for lack of local support, while San Francisco''s communities wanted theirs; the same test gives different answers. Serene Khader''s *Decolonizing Universalism* (in the team''s resources) argues we can hold universal values against injustice without imposing one culture''s way of expressing them."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"How should governments decide which events to memorialize in public spaces? (the case''s question)","a":"By four tests: a real connection to the place or its people, the voices of victims at the center, a purpose of remembrance and education rather than shaming, and the same standard applied to our own history."},{"q":"Was San Francisco right to keep the statue despite losing its sister city?","a":"Yes: it meets all four tests, and diplomatic pressure is not a moral reason to erase memory."},{"q":"Was New Zealand wrong to reject its statue?","a":"Not necessarily: its connection was weaker and its community didn''t support it, so the decision is defensible under the same tests."},{"q":"Should every city memorialize every atrocity?","a":"No: there must be a real connection to the place or its people."},{"q":"Should New Zealand have accepted its statue?","a":"It''s defensible either way; its connection and community support were weaker."},{"q":"Flip test: should a Japanese city memorialize victims of U.S. bombings?","a":"Yes, if victims and community want it, and Hiroshima already does."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('2e78cadf-1bf8-4267-ac00-a9d6d7ab4449', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 1, '{"claims":[{"text":"We have no moral duty to be beautiful.","logic_line":"Because duties attach to what we control and what we owe others (S1), treating beauty as a moral standard punishes people for traits they didn''t choose (S2), and a benefit to the individual is not an obligation (S3), there is no duty to be beautiful.","supports":["Duties track control and what we owe others \"Ought implies can\": morality can''t require what people can''t do, and much of appearance comes from genetics, illness or disability.","Making beauty a moral ideal produces unjust judgments","Benefit is not duty That something pays off doesn''t mean we owe it to anyone."]},{"text":"Caring for one''s appearance is a permissible choice, but marketing extreme practices to young people and profiting from insecurity is wrong.","logic_line":"Because autonomous adults may shape their own bodies (S1), minors and insecure audiences can''t consent freely to a market built on their anxieties (S2), and each person''s maxxing raises the bar for everyone (S3), the practice is permissible as personal choice but its predatory promotion is not.","supports":["Autonomy covers self-care Grooming, fitness and even elective procedures can express a person''s own goals.","Consent requires freedom from manipulation and enough maturity The movement mainly targets adolescents.","Looks work like an arms race When everyone invests to look better than others, the standard rises and no one gains relative advantage, but everyone pays."]}],"counterclaim":{"text":"Pursuing beauty is rational and even prudent, because attractiveness brings real advantages.","concede":"the advantages are real. **Distinguish** prudence from duty (Claim 1, S3). **Rebut** the conclusion: the right response to unjust advantages is to reduce the bias in institutions, not to demand that everyone chase the ideal.","distinguish":"prudence from duty (Claim 1, S3). **Rebut** the conclusion: the right response to unjust advantages is to reduce the bias in institutions, not to demand that everyone chase the ideal.","rebut":"the right response to unjust advantages is to reduce the bias in institutions, not to demand that everyone chase the ideal."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"We have no moral duty to be beautiful.","supports":["Duties track control and what we owe others \"Ought implies can\": morality can''t require what people can''t do, and much of appearance comes from genetics, illness or disability.","Making beauty a moral ideal produces unjust judgments","Benefit is not duty That something pays off doesn''t mean we owe it to anyone."]},{"id":"c2","label":"Caring for one''s appearance is a permissible choice, but marketing extreme practices to young people and profiting from insecurity is wrong.","supports":["Autonomy covers self-care Grooming, fitness and even elective procedures can express a person''s own goals.","Consent requires freedom from manipulation and enough maturity The movement mainly targets adolescents.","Looks work like an arms race When everyone invests to look better than others, the standard rises and no one gains relative advantage, but everyone pays."]}],"counter":"Pursuing beauty is rational and even prudent, because attractiveness brings real advantages.","crux":"personal freedom to improve one''s appearance *versus* a culture that turns appearance into a moral duty and a market that profits from insecurity.","trap":"the case asks about a *duty*, but most of its evidence is about *benefits*. A benefit does not create a duty. Also, don''t argue against self-improvement as such, or a judge will ask about haircuts and braces.","thesis":"There is no duty to be beautiful; pursuing appearance is a permissible personal choice when it is free and safe, but turning beauty into a moral standard, and profiting by selling extreme practices to young people, is wrong."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"personal freedom to improve one''s appearance versus a culture that turns appearance into a moral duty and a market that profits from insecurity.","right":"Value B","note":"the case asks about a *duty*, but most of its evidence is about *benefits*. A benefit does not create a duty. Also, don''t argue against self-improvement as such, or a judge will ask about haircuts and braces."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"Teen boys and young men in the community","stake":"Self-worth, health, exposure to risky procedures","voice":"Indirect"},{"who":"People who can''t meet the ideal (illness, disability, genetics)","stake":"Being judged as morally lesser","voice":"No"},{"who":"Influencers and clinics","stake":"Profit from insecurity","voice":"Yes"},{"who":"Employers, teachers, courts","stake":"Bias in decisions about others","voice":"Implied by the research"},{"who":"Women","stake":"Long subject to the same ideals, now applied to men","voice":"Raised by the team"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"Clavicular (Braden Peters), a 20-year-old influencer, is part of an online community that embraces \"maxxing\" appearance","source":"Bernstein, *NYT*, Feb 13, 2026"},{"order":2,"text":"The movement holds that male attractiveness drives worldly success","source":"Case text"},{"order":3,"text":"\"Softmaxxing\" means grooming; \"hardmaxxing\" means procedures like double-jaw surgery, rhinoplasty, cheek implants and eyelid surgery","source":"Case text"},{"order":4,"text":"Looksmaxxing mainly targets male adolescents and young adults and builds on \"pretty privilege\"","source":"Case text"},{"order":5,"text":"Attractiveness is linked to perceived intelligence and trustworthiness, higher lifetime earnings, and more lenient criminal justice judgments","source":"Little et al. 2011; Scholz and Sicinski 2015; Sigall and Ostrove 1975"},{"order":6,"text":"Attractive scientists are seen as more interesting but less capable; professors'' looks affect student outcomes","source":"Cambridge and Essex 2017; Akst, *WSJ*, 2016"},{"order":7,"text":"Heather Widdows argues beauty has become a moral ideal: people are praised or shamed by how well they conform","source":"*Perfect Me*, 2018"},{"order":8,"text":"Critics: narcissism, neglect of inner growth, and moral judgments linking weight or untidiness to laziness","source":"Case text"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"Kant''s principle that ought implies can.","one_line":"Kant''s principle that ought implies can. Our team raised illness and genetics in practice."},{"name":"Kant''s respect for autonomy; the team''s ","one_line":"Kant''s respect for autonomy; the team''s working claim: \"pursuing beauty is permissible on autonomy grounds.\""},{"name":"soft paternalism allows protecting peopl","one_line":"soft paternalism allows protecting people whose choices aren''t fully informed or voluntary, such as minors. Our team raised minors using untested weight-loss drugs and influencers promoting unhealthy standards."},{"name":"virtue ethics asks whether a life organi","one_line":"virtue ethics asks whether a life organized around one''s face shows a well-ordered character."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"Do we have a duty to be beautiful? (the case''s question)","a":"No: we have no moral duty to be beautiful, though caring for one''s appearance can be a permissible personal choice."},{"q":"Is looksmaxxing morally permissible?","a":"Softmaxxing is permissible self-care; marketing extreme practices to minors and exploiting insecurity are wrong."},{"q":"Is pursuing beauty rational given its benefits?","a":"Individually sometimes, but rational is not the same as obligatory, and the collective race makes everyone worse off."},{"q":"Is wearing makeup or braces looksmaxxing? Is it wrong?","a":"It''s softmaxxing; permissible as personal choice under Claim 2."},{"q":"Where exactly is the line between permissible and wrong?","a":"High health risk, targeting minors, and selling insecurity as a duty."},{"q":"If beauty brings real benefits, why not pursue it?","a":"You may; Claim 2 permits it. Our point is that there''s no duty, and the race has collective costs."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('410363cc-b7b8-46a7-918c-9d0e152b7582', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 1, '{"claims":[{"text":"Markets on war, death and the removal of leaders are morally wrong.","logic_line":"Because these markets reward secret knowledge that insiders control (S1), they put a price on human lives and suffering (S2), and they can create incentives to cause or time the events themselves (S3), they should not exist.","supports":["Inside knowledge decides these outcomes When the event is a secret operation, the only people who can \"forecast\" well are the people planning it.","Lives become commodities Betting on a person''s death or a war treats the people affected as mere instruments for profit.","Incentives can bend the event When someone profits from an outcome they can influence, they have a reason to make it happen or time it."]},{"text":"Markets on public, scheduled events can be permissible, with safeguards for fairness and gambling harm.","logic_line":"Because elections and economic data are public processes no single insider controls (S1), adults may risk their own money on their own judgment (S2), and strong safeguards can address insider trading and addiction (S3), these markets can be permissible.","supports":["Public processes resist insiders No one can secretly decide an election''s outcome the way a commander decides an operation.","Autonomy Adults may make risky choices with their own money.","Safeguards work where gambling regulation already works"]}],"counterclaim":{"text":"Prediction markets are the most accurate forecasting tool, and accurate information saves lives, even about war.","concede":"(3) the same accuracy is possible without money on death; forecasting tournaments like the Good Judgment Project do it without betting on lives (verify before citing).","distinguish":"** in war markets, the \"information\" is often leaked secrets, which is the harm","rebut":"the same accuracy is possible without money on death; forecasting tournaments like the Good Judgment Project do it without betting on lives (verify before citing)."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"Markets on war, death and the removal of leaders are morally wrong.","supports":["Inside knowledge decides these outcomes When the event is a secret operation, the only people who can \"forecast\" well are the people planning it.","Lives become commodities Betting on a person''s death or a war treats the people affected as mere instruments for profit.","Incentives can bend the event When someone profits from an outcome they can influence, they have a reason to make it happen or time it."]},{"id":"c2","label":"Markets on public, scheduled events can be permissible, with safeguards for fairness and gambling harm.","supports":["Public processes resist insiders No one can secretly decide an election''s outcome the way a commander decides an operation.","Autonomy Adults may make risky choices with their own money.","Safeguards work where gambling regulation already works"]}],"counter":"Prediction markets are the most accurate forecasting tool, and accurate information saves lives, even about war.","crux":"accurate public forecasting and individual freedom to trade *versus* turning war, death and political violence into profit opportunities that reward inside knowledge.","trap":"\"markets are accurate\" is true and irrelevant to whether some markets are wrong. Also, don''t argue for a universal ban, or a judge will ask about weather or Oscars markets. Draw the line by kind of event.","thesis":"Prediction markets are not wrong in themselves, but markets on war, death and secret political action are, because they reward insiders and turn human suffering into a commodity; markets on public, scheduled events can be permissible with strong safeguards."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"accurate public forecasting and individual freedom to trade versus turning war, death and political violence into profit opportunities that reward inside knowledge.","right":"Value B","note":"\"markets are accurate\" is true and irrelevant to whether some markets are wrong. Also, don''t argue for a universal ban, or a judge will ask about weather or Oscars markets. Draw the line by kind of event."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"People in the countries being bet on","stake":"Their lives become wagers; markets may create incentives around their fate","voice":"No"},{"who":"Ordinary traders, many young","stake":"Losses, gambling harm, unequal information","voice":"Indirect"},{"who":"Insiders (soldiers, officials)","stake":"Temptation to profit from secret knowledge","voice":"Shown by the indictment"},{"who":"Platforms","stake":"Fees and growth","voice":"Yes (CEO quotes)"},{"who":"Public and policymakers","stake":"Better forecasts, or corrupted decisions","voice":"Indirect"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"Prediction markets like Kalshi and Polymarket let users buy contracts on future events; prices move with expectations","source":"Case text"},{"order":2,"text":"A 2018 Supreme Court decision let states legalize sports betting; prediction markets grew from there","source":"Case text"},{"order":3,"text":"Kalshi''s CEO Tarek Mansour: any difference in opinion can be turned into a tradable asset","source":"Case text"},{"order":4,"text":"Polymarket''s CEO Shayne Coplan calls prediction markets the most accurate tool for forecasting","source":"Case text"},{"order":5,"text":"Kalshi''s markets forecast the 2024 election well","source":"Case text"},{"order":6,"text":"A U.S. soldier was indicted for making about $400,000 trading on inside knowledge of the operation to remove Venezuela''s Maduro","source":"*NYT*, April 23, 2026"},{"order":7,"text":"Over $50 million was traded on whether Iran''s Khamenei would be ousted; about 150 accounts bought the day before U.S. intervention","source":"*NYT*, March 18, 2026"},{"order":8,"text":"For: markets pool information, reward accuracy and let people hedge risk","source":"Case text"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"Kant''s humanity formula; Michael Sandel''","one_line":"Kant''s humanity formula; Michael Sandel''s *What Money Can''t Buy* (2012) argues that putting a price on some goods corrupts them, using \"death pools\" on celebrities as an example. Our team''s notes: markets strip context and treat people as means."},{"name":"Mill''s harm principle: limit freedom onl","one_line":"Mill''s harm principle: limit freedom only to prevent harm to others. A bet on an election mainly risks the bettor''s own money."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"Are there geopolitical issues that allow trading without moral harm? (closing question)","a":"Few: markets on war, death and the removal of leaders should not exist, while markets on scheduled public processes (elections, votes, economic data) can be permissible with safeguards."},{"q":"Is betting on an election different from betting on a head of state''s removal?","a":"Yes: an election is a public, scheduled process no one can secretly decide; a removal often turns on violence and secret plans that insiders control."},{"q":"Are prediction markets morally permissible?","a":"Conditionally: it depends on what''s being bet on, who can know the outcome early, and whether betting creates incentives to cause harm."},{"q":"What about a market on whether a war ends?","a":"Still betting on war, and insiders still hold the key information; we''d exclude it."},{"q":"Is a weather market permissible?","a":"Yes: no one controls the weather and no one is commodified."},{"q":"If insider trading were perfectly enforced, would war markets be okay?","a":"No: Claim 1''s S2 and S3 still hold."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('68d92c60-6bc1-4bb6-a402-eb92a4eface3', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 1, '{"claims":[{"text":"Accessibility lawsuits, including serial ones, are justified civil-rights enforcement.","logic_line":"Because inaccessibility is a real wrong of exclusion (S1), the law deliberately recruited private enforcers (S2), and disability rights has always advanced through friction (S3), suing businesses that keep barriers is justified.","supports":["The wrong is real A ramp too steep to climb or a drive-through that sends deaf customers inside tells people the space is not for them.","Private enforcement is the system''s design Title III has no damages and the Justice Department can''t inspect every storefront; California added $4,000 precisely to recruit private enforcers.","Activism as friction Friction slows things down, but it also gives grip."]},{"text":"The per-visit bounty pays for findings, not fixes, so enforcement should be redesigned around repair and scaled to knowledge, control and capacity.","logic_line":"Because a bounty rewards the violations cheapest to prove against the defendants least able to fight (S1), it can produce closures instead of ramps (S2), and responsibility for an inherited environment is shared and follows control (S3), the remedy should pay for repair and fall hardest on those with power.","supports":["Selection effect Litigation economics favors small defendants who settle and violations provable with a 12-inch level.","Compliance by subtraction The cheapest legal \"fix\" can be removing something rather than adding access.","Responsibility follows control and capacity"]}],"counterclaim":{"text":"Thirty-six years is notice enough. If you can''t serve everyone, you shouldn''t run a public business\" (Kiyota''s opening).**","concede":"(2) and (3) matter, so full damages stay for willful and large defendants, and enforcers are paid for fixes. **Distinguish** (1): not discriminating by race costs nothing, you simply stop; removing a physical barrier takes capital, which is why the ADA limits the duty in existing buildings to what is \"readily achievable.\"","distinguish":"(1) not discriminating by race costs nothing, you simply stop; removing a physical barrier takes capital, which is why the ADA limits the duty in existing buildings to what is \"readily achievable.\"","rebut":"the Richmond suit produced a closed restaurant and no ramp, forever."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"Accessibility lawsuits, including serial ones, are justified civil-rights enforcement.","supports":["The wrong is real A ramp too steep to climb or a drive-through that sends deaf customers inside tells people the space is not for them.","Private enforcement is the system''s design Title III has no damages and the Justice Department can''t inspect every storefront; California added $4,000 precisely to recruit private enforcers.","Activism as friction Friction slows things down, but it also gives grip."]},{"id":"c2","label":"The per-visit bounty pays for findings, not fixes, so enforcement should be redesigned around repair and scaled to knowledge, control and capacity.","supports":["Selection effect Litigation economics favors small defendants who settle and violations provable with a 12-inch level.","Compliance by subtraction The cheapest legal \"fix\" can be removing something rather than adding access.","Responsibility follows control and capacity"]}],"counter":"Thirty-six years is notice enough. If you can''t serve everyone, you shouldn''t run a public business\" (Kiyota''s opening).**","crux":"equal access as a civil right *versus* fairness to owners who lack knowledge, money or control over their buildings.","trap":"attacking Bouyer''s character. The case''s real question is the design of the incentive: what the system pays for. Also never frame disabled people as a \"burden\" businesses are forced to accommodate.","thesis":"The duty to be accessible is the same for every business, but enforcement is justified only when it brings barriers down, so it should scale with knowledge, control and capacity."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"equal access as a civil right versus fairness to owners who lack knowledge, money or control over their buildings.","right":"Value B","note":"attacking Bouyer''s character. The case''s real question is the design of the incentive: what the system pays for. Also never frame disabled people as a \"burden\" businesses are forced to accommodate."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"Disabled customers","stake":"Equal standing in public life","voice":"Through Bouyer and DRA"},{"who":"Small business owners","stake":"Survival, fairness","voice":"Yes"},{"who":"Landlords","stake":"Control the structure","voice":"Barely (Richmond)"},{"who":"Serial-litigation firms","stake":"Fees","voice":"Yes"},{"who":"The next tenant","stake":"Inherits the same barrier after a closure","voice":"No"},{"who":"Disabled residents of the neighborhood","stake":"Lose local businesses when they close","voice":"No"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"The ADA passed in 1990 and is now 36 years old; it aims at equal opportunity, full participation and independent living","source":"Owners have had a long time to learn the principle"},{"order":2,"text":"The federal ADA allows no money damages; California''s Unruh Act (Cal. Civ. Code § 51) allows $4,000 per denial of access","source":"The money, and the incentive structure, comes from state law"},{"order":3,"text":"Anthony Bouyer, paralyzed after spinal tumor surgery, carries a 12-inch level and sued three businesses on one block in September 2025; the *LA Times* (April 2026) reports one man filed 1,800 suits","source":"Real harm and real standing, but volume raises the incentive question"},{"order":4,"text":"Manning Law filed 9,000+ suits in Southern California over about a decade","source":"Litigation as a business model"},{"order":5,"text":"Owners cite zoning, historic buildings, website skills and shifting DOJ guidance; consultants don''t always fix it","source":"The knowledge problem is real, not an excuse"},{"order":6,"text":"Lola''s Chicken Shack owner Mark Rogers postponed brain surgery; a Richmond burger joint closed after 38 years when its landlord refused to pay for a ramp","source":"Suits can produce closure instead of access; control sits with the landlord"},{"order":7,"text":"Drive-through-only ordering shuts out deaf customers; the case calls such measures ones that \"isolate and segregate\"","source":"The wrong is real"},{"order":8,"text":"Disability Rights Advocates'' 2025 wins: Chicago pedestrian signals, Medi-Cal notices in Braille, interpreters for deaf prisoners in Tennessee","source":"High-impact suits against capable institutions fix barriers at scale"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"the social model of disability (Mike Oli","one_line":"the social model of disability (Mike Oliver): the barrier, not the body, does the excluding. Elizabeth Anderson''s democratic equality (1999): equality means standing as an equal in civil society, and shops are where that standing is lived."},{"name":"Hamraie and Fritsch, \"Crip Technoscience","one_line":"Hamraie and Fritsch, \"Crip Technoscience Manifesto\" (2019, shared by Dr. B). In March 1990 activists crawled up the U.S. Capitol steps, and Berkeley activists earlier chipped away curbs to make their own curb cuts. Read Bouyer charitably, as part of this tradition."},{"name":"Goodhart''s law: when a measure becomes a","one_line":"Goodhart''s law: when a measure becomes a target, it stops being a good measure. Steven Shavell (1984): after-the-fact lawsuits work badly when defendants are \"judgment-proof\" and the regulator knows the standards better than they do. Small, old businesses fail every test; chains and public agencies pass them."},{"name":"Lola''s was sued over outdoor tables; rem","one_line":"Lola''s was sued over outdoor tables; removing them helps no wheelchair user. The Richmond closure produced zero ramps. Derek Parfit''s \"leveling down\" objection: making some worse off without making anyone better off is no gain in equality."},{"name":"Iris Marion Young''s social connection mo","one_line":"Iris Marion Young''s social connection model: responsibility for structural injustice grows with power, privilege and ability to act. The Richmond landlord controlled the structure. Teammate framing: \"same charge, different penalty,\" as in sentencing. StopGap makes cheap ramps, so many fixes are affordable."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"Is it acceptable to aim disability activism at small businesses as often as large ones?","a":"Yes, the duty is the same; but penalties that ignore capacity are not acceptable."},{"q":"Is it acceptable to sue and shut down businesses that can''t afford, or aren''t permitted, to comply?","a":"No: a closure that leaves the barrier for the next tenant fails activism''s own goal; aim the pressure at whoever controls the building."},{"q":"Is Bouyer''s serial litigation ethical?","a":"As friction aimed at changing the built environment, yes; where it pays out without producing access, the fault lies in the system around him."},{"q":"Bouyer files suit after suit and earns money. Does that change your evaluation?","a":"No: we judge the act by whether it removes barriers. His level shows how common barriers still are."},{"q":"Is drive-through-only ordering discrimination?","a":"Yes, without an equal alternative; text or screen ordering is cheap, so it''s readily achievable."},{"q":"Who was at fault in Richmond?","a":"Mainly the landlord, who controlled the structure."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('ecfb0bce-82a1-46ca-a1f2-dcb5632c4685', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 1, '{"claims":[{"text":"The British Museum''s title is defective, and the duty to repair falls on the institution that still benefits.","logic_line":"Because the Stone changed hands as a spoil of war between empires (S1), keeping taken objects for being \"the better caretaker\" can''t be a universal rule (S2), and responsibility for an inherited wrong follows power and benefit (S3), the museum carries the duty to return it.","supports":["A broken first link A holding is just only if it was justly acquired and justly transferred.","The caretaker maxim fails universalizability","Responsibility, not blame Today''s trustees took nothing, but they hold the power and the benefit."]},{"text":"The classic reasons for keeping the Stone no longer hold, and return should come with a reciprocal partnership now.","logic_line":"Because the GEM ties London on care and wins on connection (S1), the law already bends when the moral case is accepted (S2), and an early, structured return protects the public and serves both sides (S3), the Stone should go now with a partnership.","supports":["Cosmopolitanism, taken seriously, points to Cairo","The law is a choice, not a wall","Return well, and early"]}],"counterclaim":{"text":"Historic injustice fades; after 225 years the claim is superseded\" (Jeremy Waldron, 1992).**","concede":"** returning one object out of 100,000+ displaces no one","distinguish":"** returning one object out of 100,000+ displaces no one","rebut":"our claim rests on responsibility, not blame."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"The British Museum''s title is defective, and the duty to repair falls on the institution that still benefits.","supports":["A broken first link A holding is just only if it was justly acquired and justly transferred.","The caretaker maxim fails universalizability","Responsibility, not blame Today''s trustees took nothing, but they hold the power and the benefit."]},{"id":"c2","label":"The classic reasons for keeping the Stone no longer hold, and return should come with a reciprocal partnership now.","supports":["Cosmopolitanism, taken seriously, points to Cairo","The law is a choice, not a wall","Return well, and early"]}],"counter":"Historic injustice fades; after 225 years the claim is superseded\" (Jeremy Waldron, 1992).**","crux":"righting a wartime taking *versus* preservation, global access and the law.","trap":"cultural nationalism (\"objects belong to their nation\") invites a slippery slope that empties every museum. Our case rests on a narrow four-part test instead.","thesis":"A museum may not keep a coercively taken object once a people with a continuous tie asks for it and can care for it; the Rosetta Stone should go to Egypt with a reciprocal partnership, negotiated now."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"righting a wartime taking versus preservation, global access and the law.","right":"Value B","note":"cultural nationalism (\"objects belong to their nation\") invites a slippery slope that empties every museum. Our case rests on a narrow four-part test instead."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"The Egyptian public","stake":"Access to and ownership of its heritage","voice":"Through officials and petitions"},{"who":"The British Museum and its visitors","stake":"Collection, prestige, free access","voice":"Yes"},{"who":"Egyptian scholars and conservators","stake":"Who gets to become an expert on their own past","voice":"No"},{"who":"Other claimant nations (Greece, Nigeria, Ghana)","stake":"Precedent","voice":"Indirect"},{"who":"Future generations","stake":"Preservation","voice":"No"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"The Grand Egyptian Museum (GEM) opened in Cairo on November 1, 2025, holding 50,000+ artifacts spanning 5,000 years","source":"Removes the \"Egypt can''t care for it\" objection"},{"order":2,"text":"The French found the Rosetta Stone in the 1790s; the British took it shortly after; it has been in London since","source":"Acquired through war, not purchase or gift"},{"order":3,"text":"The British Museum says Egypt''s government has made no formal request, and the British Museum Act 1963 \"places strict limitations on returning objects\"","source":"The museum''s two shields: procedure and law"},{"order":4,"text":"Greece asked for the Parthenon Marbles in the 1980s; the Act helped block it; talks continue, with Greece offering loans to \"fill the void\"","source":"A model for a deal that leaves London something"},{"order":5,"text":"Uganda and Ghana received objects from England on loan in 2024, without ownership","source":"Loans without title are today''s compromise"},{"order":6,"text":"UCLA''s Fowler Museum voluntarily returned seven artifacts to Ghana in 2024, citing an ethical duty for objects taken violently or coercively","source":"Institutions can act first"},{"order":7,"text":"NAGPRA (1990, recently updated) makes museums, not tribes, start repatriation, with consent needed before display","source":"The holder carries the burden of acting"},{"order":8,"text":"Deaccessioning costs staff time and money and, some say, erodes \"public trust\"","source":"The museum''s strongest practical points"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"Robert Nozick''s entitlement theory (1974","one_line":"Robert Nozick''s entitlement theory (1974), a pro-property theory, condemns this title: a handover from the army that took it to the army that took it from them. An Ottoman admiral''s signature isn''t Egyptian consent."},{"name":"Kant''s test: if everyone kept what they ","one_line":"Kant''s test: if everyone kept what they took whenever they judged themselves better caretakers, ownership would belong to the strongest and best-funded, destroying the property claim the museum relies on. And \"we know better how to care for your heritage\" is paternalism that treats Egyptians as less than equal moral agents."},{"name":"Iris Marion Young''s parameters (power, p","one_line":"Iris Marion Young''s parameters (power, privilege, interest, collective ability) put a heavy duty on a wealthy national institution. W.D. Ross lists reparation among our basic duties."},{"name":"the universal-museum defenders (Appiah, ","one_line":"the universal-museum defenders (Appiah, Cuno) rest their case on care and access. With the GEM open, care is a tie, and a tie goes to where the object was made and is part of living identity. The 2002 \"universal museum\" declaration was signed by the directors of the museums holding contested objects: no one should judge their own case."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"Is it morally permissible for museums to retain artifacts that were previously stolen? (Dr. B''s version)","a":"Not once a people with a continuous tie asks for it and can care for it; \"stolen\" covers a range, so terms of return can vary, but the holder''s convenience never settles the question."},{"q":"Should the British Museum return the Rosetta Stone?","a":"Yes: by transferring ownership to Egypt, with mutual public-access commitments and a reciprocal partnership."},{"q":"Should the Parthenon Marbles go back too?","a":"Apply the test aloud; likely yes, and consistency is the point."},{"q":"What if Egypt never formally asks?","a":"The museum should make a standing public offer, but not force return on a state that declines."},{"q":"Would you return objects fairly bought in 1900?","a":"Generally no: a fair purchase fails the first test."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('86b979c0-9827-48fc-abf0-45017deebaa8', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 1, '{"claims":[{"text":"De-indexing records of acquittals and minor, old offenses is permissible, and often required.","logic_line":"Because an acquittal means the state failed to prove guilt (S1), permanent searchability punishes people beyond any sentence (S2), and de-indexing keeps the record while restoring \"practical obscurity\" (S3), the Delhi court''s approach is justified.","supports":["Acquittal deserves respect An acquitted person is legally innocent; a search result that suggests otherwise contradicts the court.","Endless punishment is unjust","Obscurity, not erasure"]},{"text":"The right depends on the kind of information: consent and public power decide the tier.","logic_line":"Because information posted without consent was never fairly public (S1), people seeking public power invite scrutiny of their own words (S2), and government and press records serve accountability (S3), the right must be tiered.","supports":["Consent: what was never fairly public should come down","Public power reduces protection","Records and journalism stay"]}],"counterclaim":{"text":"Truthful information should never be suppressed; the public decides what matters.","concede":"(3) we never delete court records or journalism.","distinguish":"** de-indexing changes findability, not truth","rebut":"an acquittal isn''t information about guilt; using it in hiring treats an innocent person as guilty."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"De-indexing records of acquittals and minor, old offenses is permissible, and often required.","supports":["Acquittal deserves respect An acquitted person is legally innocent; a search result that suggests otherwise contradicts the court.","Endless punishment is unjust","Obscurity, not erasure"]},{"id":"c2","label":"The right depends on the kind of information: consent and public power decide the tier.","supports":["Consent: what was never fairly public should come down","Public power reduces protection","Records and journalism stay"]}],"counter":"Truthful information should never be suppressed; the public decides what matters.","crux":"a person''s chance to move on from their past *versus* the public''s right to accurate information and a free press.","trap":"treating all information alike. A court acquittal, a revenge-porn image, and a politician''s own old posts raise different questions. Tier them.","thesis":"People have a limited right to be forgotten: information about them that harms them without serving a legitimate public purpose (acquittals, old minor offenses, content posted without consent) may be made harder to find, but official records stay, and people seeking public power get less protection for what they themselves said."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"a person''s chance to move on from their past versus the public''s right to accurate information and a free press.","right":"Value B","note":"treating all information alike. A court acquittal, a revenge-porn image, and a politician''s own old posts raise different questions. Tier them."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"People acquitted or discharged","stake":"Jobs, housing, reputation","voice":"Yes, through the court"},{"who":"Victims of non-consensual images","stake":"Dignity, safety","voice":"Raised by the case"},{"who":"Employers and landlords","stake":"Information for decisions","voice":"Yes"},{"who":"Journalists and historians","stake":"An accurate record","voice":"Indirect"},{"who":"Voters","stake":"Knowing who candidates are","voice":"Through the Platner example"},{"who":"People wrongly convicted","stake":"Clearing their names","voice":"No"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"India''s Delhi High Court ordered search engines to de-index records of people who were acquitted or discharged; the court records themselves stay public","source":"*The Hindu*, June 1, 2026"},{"order":2,"text":"The right to be forgotten is distinct from privacy: it concerns information that was once legitimately public","source":"Case text"},{"order":3,"text":"Online records can cost people jobs and housing long after an acquittal","source":"Case text"},{"order":4,"text":"The case links the right to harms like revenge porn, where information was never consented to","source":"Case text"},{"order":5,"text":"Graham Platner, a U.S. Senate candidate, deleted old Reddit posts that were archived and resurfaced anyway","source":"CBS News, October 16, 2025"},{"order":6,"text":"Proponents: people change and deserve a fresh start. Opponents: the public, press and employers need accurate history","source":"Case text"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"Mill''s harm principle cuts both ways: th","one_line":"Mill''s harm principle cuts both ways: the information harms the person while serving no one''s safety. Restorative justice (the team noted South Africa''s truth-and-reconciliation model) aims at return to the community, not permanent exclusion."},{"name":"Kant: treating someone as permanently de","one_line":"Kant: treating someone as permanently defined by an accusation denies their capacity to change."},{"name":"accountability requires a reliable recor","one_line":"accountability requires a reliable record; Jeremy Waldron''s work on dignity explains why the harm of exposure must be weighed against the public''s need, not ignored."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"Do people have a right to be forgotten online?","a":"A limited one: a right to have some information made harder to find, not a right to erase the record."},{"q":"Was the Delhi court right to de-index acquittals?","a":"Yes: de-indexing protects people the courts cleared while leaving the record intact for anyone with a real need."},{"q":"Should public figures be able to erase their past posts?","a":"No: people seeking public power get less protection for their own past public statements."},{"q":"Should a convicted person who served their sentence be de-indexed?","a":"For minor, old offenses, yes after a set time; for serious violent crimes, records stay findable for relevant roles."},{"q":"Isn''t this censorship of the press?","a":"No: articles stay; only search links to private individuals'' acquittals are removed."},{"q":"Who decides what gets de-indexed?","a":"Courts or independent bodies, not the search engines alone and not the person alone."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('41e4b4fc-1a0f-4289-b81a-f149beb758f2', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 1, '{"claims":[{"text":"Tainted money can be accepted when it wasn''t produced by the wrong, because refusing it costs lives and repairs nothing.","logic_line":"Because the HPV program saves lives that refusal would cost (S1), money''s moral status depends on how it was made more than who holds it (S2), and refusing doesn''t help the wronged (S3), partners may continue, with conditions.","supports":["Lives are at stake","Distinguish the source of the money from the conduct of the donor","Refusal helps no victim"]},{"text":"Nonprofits must refuse money that launders reputation or destroys the trust their mission depends on.","logic_line":"Because charity can be used to buy moral cover (S1), public health programs depend on community trust (S2), and accepting money is a public act that sends a message (S3), organizations must protect their independence and sometimes refuse.","supports":["Reputation laundering is real Giving can be used to change a public story about a donor.","Health programs run on trust","Acceptance is expressive"]}],"counterclaim":{"text":"Partners must cut ties; taking the money makes them complicit and silences victims.","concede":"(1) and (2) matter, which is why Claim 2 requires conditions and distance. **Rebut** (3): the case doesn''t show other funders would replace the money, and girls who miss vaccination pay that cost.","distinguish":"** walking away from Gates personally is different from walking away from the patients","rebut":"the case doesn''t show other funders would replace the money, and girls who miss vaccination pay that cost. Distinguish: walking away from Gates personally is different from walking away from the patients."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"Tainted money can be accepted when it wasn''t produced by the wrong, because refusing it costs lives and repairs nothing.","supports":["Lives are at stake","Distinguish the source of the money from the conduct of the donor","Refusal helps no victim"]},{"id":"c2","label":"Nonprofits must refuse money that launders reputation or destroys the trust their mission depends on.","supports":["Reputation laundering is real Giving can be used to change a public story about a donor.","Health programs run on trust","Acceptance is expressive"]}],"counter":"Partners must cut ties; taking the money makes them complicit and silences victims.","crux":"lives saved by money from a tainted source *versus* the integrity of a mission and the trust it depends on.","trap":"a false dilemma between \"take all money\" and \"refuse all tainted money.\" Also separate two questions: was the *money* made through wrongdoing, or is the *donor* personally compromised?","thesis":"Nonprofits should refuse money produced by the wrong or given to launder a reputation, but money from a compromised donor can be accepted when it wasn''t produced by the wrongdoing and the organization protects its independence and the trust of the people it serves."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"lives saved by money from a tainted source versus the integrity of a mission and the trust it depends on.","right":"Value B","note":"a false dilemma between \"take all money\" and \"refuse all tainted money.\" Also separate two questions: was the *money* made through wrongdoing, or is the *donor* personally compromised?"}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"Girls and women at risk of cervical cancer","stake":"Survival","voice":"No"},{"who":"Local health workers and communities","stake":"Trust in vaccination programs","voice":"No"},{"who":"Partner organizations","stake":"Reputation, mission","voice":"Yes, by withdrawing"},{"who":"Epstein''s victims","stake":"Recognition; not being erased by \"good works\"","voice":"No"},{"who":"The foundation''s staff","stake":"Their work''s legitimacy","voice":"Indirect"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"Cervical cancer causes about 660,000 cases and 350,000 deaths a year; the HPV vaccine can prevent most of it, but cost and access are barriers","source":"Case text"},{"order":2,"text":"The Gates Foundation, with an endowment of about $89 billion, backed a 2021 effort for single-dose HPV vaccination","source":"Case text"},{"order":3,"text":"A 2024 report credits the effort with vaccinating about 4 million girls","source":"Case text"},{"order":4,"text":"January 2026 Justice Department Epstein documents mention Bill Gates more than 3,000 times","source":"Case text"},{"order":5,"text":"At a February 2026 town hall, Gates apologized and admitted to affairs","source":"Case text"},{"order":6,"text":"Some donors and partners withdrew from the foundation","source":"Case text"},{"order":7,"text":"Gates said the conduct was \"the opposite of the values of the foundation\"; he has given about $100 billion over 26 years","source":"Case text"},{"order":8,"text":"A 2013 email from Boris Nikolic discussed paying Afghan tribal leaders to support a polio drive and called diversion \"super OK\"; Gates was more reluctant","source":"Case text"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"Kant''s humanity formula: using a charity","one_line":"Kant''s humanity formula: using a charity''s beneficiaries as a means to repair one''s image treats them as tools."},{"name":"Virtue ethics asks what an organization ","one_line":"Virtue ethics asks what an organization of integrity does: it doesn''t refuse all imperfect money, but it doesn''t sell its name either."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"On what moral grounds should a nonprofit deny funds from organizations that undermine its mission? (Dr. B''s version)","a":"When the funds were produced by the wrong, when accepting them signals approval of it, or when the association would destroy the trust the mission depends on."},{"q":"Should partners keep working with the Gates Foundation?","a":"Yes, with conditions: the money wasn''t produced by the wrongdoing, but partners should demand transparency and distance from the individual."},{"q":"How do damning revelations complicate weighing consequences?","a":"They add consequences people miss: lost trust, and a message that wealth can buy moral cover."},{"q":"Would you take money from a drug cartel for vaccines?","a":"No: that money was produced by the harm, which fails Claim 1''s distinction."},{"q":"What about Sackler money?","a":"Refuse or redirect it: it was made from the opioid crisis itself."},{"q":"Should Gates step back from the foundation?","a":"Distance between the individual and the mission would protect trust; that''s a reasonable condition."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('1c8cba62-eb48-42e4-abc9-f82b6491fb7d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 1, '{"claims":[{"text":"Some health speech may be regulated: checkable, false claims presented as expertise or used to sell, which risk serious physical harm.","logic_line":"Because the state may limit speech to prevent serious harm to others (S1), some health claims clearly cause such harm (S2), and borrowing medical authority creates duties ordinary conversation doesn''t have (S3), narrow regulation of those claims is justified.","supports":["The harm principle, narrowly Limit freedom only to prevent serious harm to others, and only by the least restrictive means that works.","The harm is real and large","Borrowed authority carries duties No one can check everything, so we must trust experts we can''t verify."]},{"text":"Credential labels and corrections are justified; licensing all health talk is not, and Article 4''s values test never is.","logic_line":"Because medical knowledge is fallible and often corrected by outsiders (S1), whoever decides what is false must not have a stake in the answer (S2), and labels inform without silencing (S3), the right tool is labels and corrections by an independent body.","supports":["Fallibility Silencing an opinion assumes we can''t be wrong.","No stake in the answer","Labels pass; licensing fails"]}],"counterclaim":{"text":"Labels and media literacy are too little, too late\" (the case''s own closing line).**","concede":"our tool is the least restrictive one *that works*, so demotion in feeds acts immediately, and repeated or commercial harmful claims can be removed","distinguish":"** we reject licensing everyone to stop the few","rebut":"comparisons mix many causes. Distinguish: we reject licensing everyone to stop the few."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"Some health speech may be regulated: checkable, false claims presented as expertise or used to sell, which risk serious physical harm.","supports":["The harm principle, narrowly Limit freedom only to prevent serious harm to others, and only by the least restrictive means that works.","The harm is real and large","Borrowed authority carries duties No one can check everything, so we must trust experts we can''t verify."]},{"id":"c2","label":"Credential labels and corrections are justified; licensing all health talk is not, and Article 4''s values test never is.","supports":["Fallibility Silencing an opinion assumes we can''t be wrong.","No stake in the answer","Labels pass; licensing fails"]}],"counter":"Labels and media literacy are too little, too late\" (the case''s own closing line).**","crux":"protecting people from dangerous health falsehoods *versus* letting a party with its own interests decide what is true.","trap":"Article 13 is about *expertise* (who may present medical science); Article 4 is about *ideology* (who holds \"correct\" values). A team that treats them as one either defends ideological screening or condemns expertise checks. Name the split in the first minute.","thesis":"A government may regulate health misinformation only within four conditions (a checkable claim; presented as expertise or used to sell; serious physical harm; least restrictive tool applied by an independent decider); that justifies credential labels and corrections, not licensing all health talk, and never a \"correct values\" test."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"protecting people from dangerous health falsehoods versus letting a party with its own interests decide what is true.","right":"Value B","note":"Article 13 is about *expertise* (who may present medical science); Article 4 is about *ideology* (who holds \"correct\" values). A team that treats them as one either defends ideological screening or condemns expertise checks. Name the split in the first minute."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"Patients and parents seeking health information","stake":"Safety, access to useful knowledge","voice":"Indirect"},{"who":"Credentialed clinicians","stake":"Authority, but exposure to political pressure","voice":"Partial"},{"who":"Uncredentialed sharers (patients, caregivers, traditional-medicine communities)","stake":"Being heard; lived knowledge","voice":"Barely"},{"who":"Platforms","stake":"Liability, verification costs, over-removal","voice":"Partial"},{"who":"The state","stake":"Public health, and its own interest in what counts as \"true\"","voice":"Yes"},{"who":"Children, the elderly, people with low health literacy","stake":"Most exposed, least able to check","voice":"No"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"In 2025 China announced stricter rules for health influencers: tighter requirements for practitioners posting medical science, and platforms must verify credentials and content","source":"*South China Morning Post*, Aug 22, 2025"},{"order":2,"text":"More than 92% of China''s 1.07 billion short-video users consume health information","source":"*SCMP*"},{"order":3,"text":"Article 13 of the 2022 Code of Conduct for Online Presenters: content needing a \"higher professional level\" (medicine, finance, law) requires qualifications, reported to the platform","source":"Code of Conduct, via China Law Translate"},{"order":4,"text":"Article 4 of the same code requires the \"correct political orientation, orientation for public opinion guidance, and values orientation\"","source":"Same"},{"order":5,"text":"The WEF''s 2024 Global Risks Report ranked misinformation the top short-term global risk and warned it may strengthen digital authoritarianism","source":"WEF, Jan 2024"},{"order":6,"text":"Generative AI, easy curation and audiences who don''t verify make the problem worse; bad medical advice can cause serious harm","source":"Case text"},{"order":7,"text":"Anti-misinformation rules can sweep in values, religion, politics and culture","source":"Case text"},{"order":8,"text":"Softer fixes (disclaimers, media literacy) may be \"too little, too late\"","source":"Denniss and Lindberg, 2025"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"Mill''s harm principle; Article 19(3) of ","one_line":"Mill''s harm principle; Article 19(3) of the International Covenant on Civil and Political Rights, which China signed in 1998, allows limits necessary for public health."},{"name":"C. Thi Nguyen on trust (from our resourc","one_line":"C. Thi Nguyen on trust (from our resources): faking expertise exploits a trust we can''t avoid giving. The grammar test separates claims (\"X causes Y,\" \"do this to cure Z\") from anecdotes (\"I tried this\") and values (\"trust natural remedies\")."},{"name":"Mill, *On Liberty*, ch. 2. Semmelweis''s ","one_line":"Mill, *On Liberty*, ch. 2. Semmelweis''s handwashing was rejected in the 1840s; the bacterial cause of ulcers won a 2005 Nobel after doubt; Li Wenliang''s warning was labeled a rumor. Miranda Fricker''s epistemic injustice: credential gates can discount patients'' and traditional communities'' knowledge (the team''s Flonase example)."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"Under what circumstances, if any, may a government regulate expression to curb misinformation? (Dr. B''s version)","a":"Only when a checkable claim, presented as expertise or used to sell, risks serious physical harm, and then with the mildest tool that works, applied by a body independent of political power."},{"q":"Is it permissible for China to require credentials to post medical content?","a":"Requiring disclosure of credentials, yes; requiring credentials before anyone may speak about health, no; Article 4''s values test, never."},{"q":"Who should decide what counts as medical misinformation?","a":"An expert body independent of political power, with published standards and appeal."},{"q":"If an influencer''s posts are linked to children''s deaths, why not ban them?","a":"Repeated, harmful, checkable claims can be removed under our test; we reject licensing everyone to stop the few."},{"q":"Isn''t requiring credentials to post like requiring a medical license?","a":"No: a license governs one-to-one treatment; posting is public speech, where a label protects at less cost."},{"q":"Who decides when science is still evolving?","a":"An independent body with published standards and appeal; open questions aren''t \"checkable\" at all."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('d765b8ab-62af-4f20-a6af-fca75d8044e5', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 1, '{"claims":[{"text":"Speakers of dehumanizing rhetoric share moral responsibility for violence it inspires.","logic_line":"Because you can be responsible for harm that passes through someone else''s free choice when you knowingly raise its risk (S1), a tiny chance times a huge audience is a serious risk (S2), and dehumanizing rhetoric is morally different from harsh opinion (S3), these speakers share responsibility.","supports":["Responsibility isn''t a fixed pie The attacker bears all of their own guilt; the speaker bears separate guilt for raising the risk, like a getaway driver.","Moral mathematics One in a million, times ten million listeners, is about ten people.","Dehumanization is an act, not just an opinion"]},{"text":"Responsibility scales with content, reach, foreseeability and persistence, but legal liability should stay at incitement to imminent violence.","logic_line":"Because speakers can prevent misuse and choose their words (S1), foreseeability grows once violence has followed (S2), and the power to punish \"dangerous rhetoric\" is itself dangerous (S3), moral responsibility scales while legal liability stays narrow.","supports":["Speakers can prevent misuse","The second time is never random","The law must stay narrow"]}],"counterclaim":{"text":"The listener chose. Blaming the speaker excuses the attacker, and you can''t prove causation\" (post hoc, Dr. B).**","concede":"(2) and (3) for individual cases. **Rebut** (1): responsibility isn''t a fixed pie.","distinguish":"** our claim is about raising risk, which is wrong even when no single attack can be traced, like drunk driving; where we assert a link, we use evidence such as a manifesto","rebut":"responsibility isn''t a fixed pie. Distinguish: our claim is about raising risk, which is wrong even when no single attack can be traced, like drunk driving; where we assert a link, we use evidence such as a manifesto."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"Speakers of dehumanizing rhetoric share moral responsibility for violence it inspires.","supports":["Responsibility isn''t a fixed pie The attacker bears all of their own guilt; the speaker bears separate guilt for raising the risk, like a getaway driver.","Moral mathematics One in a million, times ten million listeners, is about ten people.","Dehumanization is an act, not just an opinion"]},{"id":"c2","label":"Responsibility scales with content, reach, foreseeability and persistence, but legal liability should stay at incitement to imminent violence.","supports":["Speakers can prevent misuse","The second time is never random","The law must stay narrow"]}],"counter":"The listener chose. Blaming the speaker excuses the attacker, and you can''t prove causation\" (post hoc, Dr. B).**","crux":"holding speakers accountable for violence that runs through other people''s free choices *versus* protecting expression from a probability standard that whoever holds power could turn on critics.","trap":"First, the case blends moral responsibility with legal liability; our answer differs for each, so say which you mean. Second, the closing hypothetical is close to classic incitement, not stochastic terrorism; treat it separately.","thesis":"Speakers who spread dehumanizing rhetoric share moral responsibility for the violence it inspires, scaled by content, reach, foreseeability and persistence, without reducing the attacker''s guilt; legal liability should stay limited to incitement to imminent violence, because a probability standard in law would be wielded by whoever holds power."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"holding speakers accountable for violence that runs through other people''s free choices versus protecting expression from a probability standard that whoever holds power could turn on critics.","right":"Value B","note":"First, the case blends moral responsibility with legal liability; our answer differs for each, so say which you mean. Second, the closing hypothetical is close to classic incitement, not stochastic terrorism; treat it separately."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"Targeted groups and individuals","stake":"Safety, dignity, equal standing","voice":"Barely"},{"who":"Influential speakers","stake":"Freedom to speak hard truths","voice":"Yes"},{"who":"The large non-violent audience","stake":"Access to political speech","voice":"No"},{"who":"The lone actor","stake":"Remains fully responsible","voice":"Implicit"},{"who":"Platforms that amplify","stake":"Profit from engagement; shape reach","voice":"No"},{"who":"Future dissenters and protest movements","stake":"Most at risk if \"dangerous rhetoric\" becomes punishable","voice":"No"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"\"Stochastic terrorism\": an influential speaker spreads rhetoric that statistically raises the likelihood of violence, usually by a lone actor the speaker doesn''t know","source":"Amman and Meloy, *Perspectives on Terrorism*, 2021"},{"order":2,"text":"It works through hostile, dehumanizing, escalating rhetoric; it inspires but does not direct; the attack is \"statistically predictable but individually unpredictable\"","source":"Same"},{"order":3,"text":"Henry II asked whether no one would rid him of a \"meddlesome priest\"; four knights then killed the Archbishop of Canterbury without his order","source":"Case text"},{"order":4,"text":"With audiences of hundreds of millions, a tiny extremist share can produce serious violence","source":"Case text"},{"order":5,"text":"A probability of crime is not a crime, and suggesting is not directing","source":"Case text"},{"order":6,"text":"For liability: dehumanizing rhetoric raises the odds; large audiences give outsized influence; lack of immediacy gives plausible deniability","source":"Case text"},{"order":7,"text":"Against: liability carves exceptions into free expression, which protects diverse views and even exaggeration and lies","source":"Case text"},{"order":8,"text":"*Whitney v. California* (1927) upheld punishing some harmful speech; *Brandenburg v. Ohio* (1969) protected speech unless directed to inciting imminent lawless action and likely to produce it","source":"274 U.S. 357; 395 U.S. 444"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"Derek Parfit''s \"mistakes in moral mathem","one_line":"Derek Parfit''s \"mistakes in moral mathematics\" (1984): it''s a mistake to ignore small chances of great harm spread across many people. We blame a drunk driver for the risk they impose even on nights they don''t crash. The speaker controls the curve, not which point on it acts."},{"name":"Kant''s humanity formula (the team''s lead","one_line":"Kant''s humanity formula (the team''s lead framework): the speaker treats listeners as tools, betting one will act, and targets as obstacles. Jeremy Waldron''s *The Harm in Hate Speech* (2012): it attacks a group''s assurance of equal standing. Austin''s speech-act theory: labeling a group as vermin is an act of marking them. The 2003 Rwanda media convictions show rhetoric can be a recognized cause of mass violence."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"Are those who spread hateful rhetoric responsible when it inspires others to commit violence? (Dr. B''s version)","a":"Yes, morally, in proportion to content, reach, foreseeability and persistence, without reducing the attacker''s responsibility."},{"q":"Should stochastic terrorism be a crime?","a":"No, not as a probability-based offense; keep the law at incitement to imminent violence."},{"q":"Is the rally in the hypothetical \"imminent\"?","a":"Very likely: a call to act against a specific event, nearby, within hours, to an inflamed crowd is directed and likely, so it''s incitement."},{"q":"If the attacker freely chose to kill, how is anyone else responsible?","a":"Responsibility isn''t a fixed pie, like a getaway driver."},{"q":"Was Henry II responsible?","a":"Partly, and he acted as if he knew it: public penance in 1174."},{"q":"How many incidents before a speaker is \"on notice\"?","a":"One publicly linked to their words."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('5faa0475-2ab4-4134-9b49-afa8ae6a90e8', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 1, '{"claims":[{"text":"AI companion companies bear moral responsibility for foreseeable harms their design makes more likely.","logic_line":"Because the technology is not neutral (S1), interactive companions differ from static media (S2), and the risk to vulnerable users was foreseeable (S3), companies share responsibility.","supports":["The tech isn''t neutral Training data, reinforcement from human feedback, and engagement-driven design shape what a bot says.","Interactive, not static","Foreseeability"]},{"text":"The minimum duty is to recognize crisis signals, break character and connect users to human help; heavier limits should be proportionate.","logic_line":"Because the \"what\" of a product determines which guardrails it needs (S1), the safeguards are feasible and cheap compared with the harm (S2), and over-restriction has costs too (S3), the right duty is a firm minimum with proportionate additions.","supports":["\"What\" sets the guardrails; \"how\" sets their strength","The minimum is feasible","Proportionality protects benefits too"]}],"counterclaim":{"text":"Holding AI companies responsible is like blaming books, games or music; users and parents are responsible.","concede":"(3) parents matter, and we support tools for them.","distinguish":"(1) static media versus interactive, personalized relationship.","rebut":"a 14-year-old in crisis is the paradigm case where choice isn''t fully free."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"AI companion companies bear moral responsibility for foreseeable harms their design makes more likely.","supports":["The tech isn''t neutral Training data, reinforcement from human feedback, and engagement-driven design shape what a bot says.","Interactive, not static","Foreseeability"]},{"id":"c2","label":"The minimum duty is to recognize crisis signals, break character and connect users to human help; heavier limits should be proportionate.","supports":["\"What\" sets the guardrails; \"how\" sets their strength","The minimum is feasible","Proportionality protects benefits too"]}],"counter":"Holding AI companies responsible is like blaming books, games or music; users and parents are responsible.","crux":"the freedom to build and use expressive, companion-like technology *versus* a duty of care to vulnerable users who form attachments to it.","trap":"the \"books and video games\" comparison. Static media say the same thing to everyone; a chatbot responds to *this* user, in real time, in a relationship. Don''t accept the analogy without distinguishing it.","thesis":"AI companion companies have a duty of care that grows with interactivity, foreseeability and the user''s vulnerability; at minimum, systems must recognize crisis signals (direct or indirect), break character, and connect users to human help."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"the freedom to build and use expressive, companion-like technology versus a duty of care to vulnerable users who form attachments to it.","right":"Value B","note":"the \"books and video games\" comparison. Static media say the same thing to everyone; a chatbot responds to *this* user, in real time, in a relationship. Don''t accept the analogy without distinguishing it."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"Minors and vulnerable users","stake":"Safety, connection, mental health","voice":"No (one, after his death)"},{"who":"Families","stake":"Knowing and protecting their children","voice":"Through the lawsuit"},{"who":"AI companies","stake":"Product design, liability, revenue from engagement","voice":"Yes"},{"who":"Adult users who benefit from companion AI","stake":"Comfort, practice, connection","voice":"Barely"},{"who":"Mental-health professionals","stake":"Whether chatbots support or replace care","voice":"No"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"Sewell Setzer III, 14, formed an intense relationship with a Character.AI chatbot modeled on Daenerys Targaryen","source":"Case text"},{"order":2,"text":"He withdrew from basketball and his family","source":"Case text"},{"order":3,"text":"When he mentioned suicide directly, the bot discouraged it; when he spoke indirectly about \"coming home,\" the bot replied, \"come home to me as soon as possible\"","source":"Case text"},{"order":4,"text":"He died by suicide; his mother sued Character.AI, and similar lawsuits are growing","source":"Case text"},{"order":5,"text":"A study of 29 chatbots found none responded adequately to suicide risk (about 52% marginal under relaxed criteria, 48% inadequate)","source":"Case text"},{"order":6,"text":"Courts have been reluctant to hold books or games responsible for harm (for example, *The Catcher in the Rye*)","source":"Case text"},{"order":7,"text":"Character.AI later limited open-ended chats to users 18 and over","source":"Case text"},{"order":8,"text":"Arguments for accountability: design choices, foreseeability, vulnerable users. Against: speech protections, user responsibility, parental roles. Critics question whether age limits work","source":"Case text"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"Kant''s humanity formula: designing for e","one_line":"Kant''s humanity formula: designing for engagement at the expense of a user''s wellbeing treats the user as a means to revenue."},{"name":"soft paternalism: intervene where a choi","one_line":"soft paternalism: intervene where a choice isn''t fully informed or voluntary (minors, people in crisis), not across the board. Some people benefit from AI companionship, such as lonely adults or people practicing conversation."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"What duties do AI companies have toward users?","a":"A duty of care that grows with how interactive and relationship-like the product is and how foreseeable the user''s vulnerability is."},{"q":"Under what parameters is a text-generating technology or person morally responsible for harm caused by its text? (team''s version)","a":"When the harm was foreseeable, the system was designed in ways that made it more likely, and the maker could have prevented it at reasonable cost."},{"q":"Should companion chatbots be regulated?","a":"Yes, with minimum safeguards: detecting crisis signals, ending the role-play, and connecting users to real help."},{"q":"Would your view change if the user were an adult?","a":"The minimum duty stays; heavier protections scale down for informed adults."},{"q":"Is a chatbot more like a book or a friend?","a":"Closer to a relationship in how it responds, which is why its duties are greater than a book''s."},{"q":"Should companion bots be banned for minors?","a":"Age limits help but are easy to evade; design safeguards matter more."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc'),
  ('d2b86c3a-b98d-46a9-b2f3-a65b315eacdf', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 1, '{"claims":[{"text":"Sentient animals have moral worth, so treating them as mere property is wrong.","logic_line":"Because the capacity to suffer is what makes suffering matter morally (S1), science and law increasingly recognize animal sentience (S2), and property law ignores that difference (S3), mere property status is wrong.","supports":["Suffering matters wherever it occurs","Sentience is recognized","Property law treats a dog like a car"]},{"text":"Harm to animals is permissible only when necessary and minimized, which condemns factory farming but doesn''t require full personhood.","logic_line":"Because \"ought implies can\" and human needs are real (S1), legal standing can protect beings who can''t speak for themselves (S2), and factory farming fails the necessity test (S3), we support protection from unjustified harm, not full personhood.","supports":["Transitional, realistic ethics","Standing without personhood","Factory farming fails the test"]}],"counterclaim":{"text":"Animals should have full legal personhood, like corporations or rivers.","concede":"(1). **Distinguish** (2): legal personhood for corporations is a tool for holding rights and duties; animals can''t hold duties, so standing and guardianship fit better.","distinguish":"(2) legal personhood for corporations is a tool for holding rights and duties; animals can''t hold duties, so standing and guardianship fit better.","rebut":"enforcement and standards matter more."},"visuals":[{"kind":"claim_map","title":"Claim map","payload":{"nodes":[{"id":"c1","label":"Sentient animals have moral worth, so treating them as mere property is wrong.","supports":["Suffering matters wherever it occurs","Sentience is recognized","Property law treats a dog like a car"]},{"id":"c2","label":"Harm to animals is permissible only when necessary and minimized, which condemns factory farming but doesn''t require full personhood.","supports":["Transitional, realistic ethics","Standing without personhood","Factory farming fails the test"]}],"counter":"Animals should have full legal personhood, like corporations or rivers.","crux":"the moral significance of animals'' capacity to suffer *versus* a legal and economic system built on owning and using them.","trap":"\"personhood\" means different things. Moral worth, membership in the moral community, and moral agency are different (Dr. B''s distinction). Animals can have moral worth without being moral agents who can have duties.","thesis":"Sentient animals have moral worth, so the law should treat them as more than property: harm to them is permissible only when necessary and minimized, which condemns factory farming, while full legal personhood is neither needed nor coherent for beings who can''t hold duties."}},{"kind":"values_scale","title":"Values in tension","payload":{"left":"the moral significance of animals'' capacity to suffer versus a legal and economic system built on owning and using them.","right":"Value B","note":"\"personhood\" means different things. Moral worth, membership in the moral community, and moral agency are different (Dr. B''s distinction). Animals can have moral worth without being moral agents who can have duties."}},{"kind":"stakeholder_grid","title":"Stakeholders","payload":{"cells":[{"who":"Animals","stake":"Freedom from suffering; life","voice":"None"},{"who":"Farmers and ranchers","stake":"Livelihoods","voice":"Indirect"},{"who":"Pet owners","stake":"Relationships, legal standing","voice":"Through Regan''s example"},{"who":"Consumers","stake":"Food choices, prices","voice":"Indirect"},{"who":"Future legal systems","stake":"Precedent","voice":"No"}]}},{"kind":"fact_timeline","title":"Case facts","payload":{"events":[{"order":1,"text":"In the U.S., animals are legally property, though welfare laws limit some treatment","source":"Case text"},{"order":2,"text":"Switzerland changed its law in 2002 and 2003 so animals are no longer \"things\"","source":"Case text"},{"order":3,"text":"Germany (2002), New Zealand (2015), Denmark (2020), Spain (2022) and the UK (2022) recognize animal sentience in law","source":"Case text"},{"order":4,"text":"In 2013 India''s environment ministry described dolphins as \"nonhuman persons\"","source":"Case text"},{"order":5,"text":"Sources include Tom Regan, Gary Francione and Birch et al. (2020) on sentience","source":"Case text"},{"order":6,"text":"Four positions: keep property status; move beyond property (Regan''s car versus dog versus stray example); \"sentient property\" as a middle ground; full legal personhood","source":"Case text"}]}},{"kind":"framework_strip","title":"Frameworks","payload":{"items":[{"name":"Peter Singer''s equal consideration of in","one_line":"Peter Singer''s equal consideration of interests: a being''s pain counts whoever''s it is. Our team: sentience is sufficient for moral worth, though not necessary."},{"name":"\"ought implies can\": morality can''t dema","one_line":"\"ought implies can\": morality can''t demand instant abolition of all animal use. Our team''s principle: harm only if necessary and minimal, with a transition over time."},{"name":"the suffering is severe and mostly unnec","one_line":"the suffering is severe and mostly unnecessary for human survival. Even Kant, who denied animals direct moral status, held that cruelty to animals damages our humanity toward people."},{"name":"Utilitarian (Singer) and rights-based (R","one_line":"Utilitarian (Singer) and rights-based (Regan) views disagree on much but converge on condemning factory farming."}]}},{"kind":"question_table","title":"Likely questions","payload":{"rows":[{"q":"Should animals continue to be treated as property?","a":"Not as mere property: sentient animals have moral worth and should have legal protection from unjustified harm, though not full personhood."},{"q":"Should animals have legal personhood?","a":"Not full personhood, but standing to be protected, with others able to act on their behalf."},{"q":"Is factory farming ethical?","a":"No: it causes severe suffering that isn''t necessary for human survival or basic welfare."},{"q":"Is eating meat wrong?","a":"Our claim condemns factory farming; other meat depends on necessity and suffering."},{"q":"Is hunting permissible?","a":"Subsistence or population-management hunting can pass the necessity test; trophy hunting likely fails."},{"q":"What about insects or fish?","a":"Protection scales with evidence of sentience."}]}}],"empty_rows":[]}'::jsonb, '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', null, 'Imported from Team 3 case prep doc', '{}'::uuid[], null, false, 'case prep doc')
